using System;using Ashfall.Core;using Ashfall.Modules.Construction;using Ashfall.Modules.ConstructionCandidate;using Ashfall.Integration.Playable.HandsWeapons;
namespace Ashfall.Integration.Playable.Networking {
 // Exact convex source blade hull against the same host body spheres used by rays.
 // No invisible remote Unity colliders, client target lists, or sparse sweep rays.
 internal static class R24LanMeleeGeometry {
  static Float3 Sub(Float3 a,Float3 b){return R24KnifeMath.Sub(a,b);}static float Dot(Float3 a,Float3 b){return R23WeaponPoseMath.Dot(a,b);}static Float3 Cross(Float3 a,Float3 b){return R23WeaponPoseMath.Cross(a,b);}static Float3 Add(Float3 a,Float3 b){return R24KnifeMath.Add(a,b);}static Float3 Scale(Float3 a,float n){return R24KnifeMath.Scale(a,n);}
  static Float3 Closest(Float3 p,Float3 a,Float3 b,Float3 c){var ab=Sub(b,a);var ac=Sub(c,a);var ap=Sub(p,a);float d1=Dot(ab,ap),d2=Dot(ac,ap);if(d1<=0&&d2<=0)return a;var bp=Sub(p,b);float d3=Dot(ab,bp),d4=Dot(ac,bp);if(d3>=0&&d4<=d3)return b;float vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0)return Add(a,Scale(ab,d1/(d1-d3)));var cp=Sub(p,c);float d5=Dot(ab,cp),d6=Dot(ac,cp);if(d6>=0&&d5<=d6)return c;float vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0)return Add(a,Scale(ac,d2/(d2-d6)));float va=d3*d6-d5*d4;if(va<=0&&d4-d3>=0&&d5-d6>=0)return Add(b,Scale(Sub(c,b),(d4-d3)/(d4-d3+d5-d6)));float inv=1/(va+vb+vc);return Add(a,Add(Scale(ab,vb*inv),Scale(ac,vc*inv)));}
  internal static bool Sphere(Float3[] v,int[] t,Float3 center,float radius){bool inside=true;for(int i=0;i<t.Length;i+=3){var a=v[t[i]];var b=v[t[i+1]];var c=v[t[i+2]];if(Dot(Cross(Sub(b,a),Sub(c,a)),Sub(center,a))>.000001f)inside=false;var d=Sub(center,Closest(center,a,b,c));if(Dot(d,d)<=radius*radius)return true;}return inside;}
  static bool Apart(Float3[] a,Float3[] b,Float3 axis){if(Dot(axis,axis)<1e-12f)return false;float amin=float.PositiveInfinity,amax=float.NegativeInfinity,bmin=float.PositiveInfinity,bmax=float.NegativeInfinity;foreach(var p in a){float n=Dot(p,axis);amin=Math.Min(amin,n);amax=Math.Max(amax,n);}foreach(var p in b){float n=Dot(p,axis);bmin=Math.Min(bmin,n);bmax=Math.Max(bmax,n);}return amin>bmax||bmin>amax;}
  internal static bool Hulls(Float3[] a,int[] ta,Float3[] b,int[] tb){foreach(var pair in new[]{ta,tb}){var v=Object.ReferenceEquals(pair,ta)?a:b;for(int i=0;i<pair.Length;i+=3)if(Apart(a,b,Cross(Sub(v[pair[i+1]],v[pair[i]]),Sub(v[pair[i+2]],v[pair[i]]))))return false;}for(int i=0;i<ta.Length;i++)for(int j=0;j<tb.Length;j++)if(Apart(a,b,Cross(Sub(a[ta[i]],a[ta[i/3*3+(i+1)%3]]),Sub(b[tb[j]],b[tb[j/3*3+(j+1)%3]]))))return false;return true;}
  static bool Separated(Float3[] v,Float3 center,Float3 half,Float3 axis){if(Dot(axis,axis)<.0000000001f)return false;float min=Single.PositiveInfinity,max=Single.NegativeInfinity;foreach(var p in v){float n=Dot(Sub(p,center),axis);min=Math.Min(min,n);max=Math.Max(max,n);}float r=half.X*Math.Abs(axis.X)+half.Y*Math.Abs(axis.Y)+half.Z*Math.Abs(axis.Z);return min>r||max< -r;}
  internal static bool Box(Float3[] v,int[] triangles,Panel piece){foreach(var box in CandidateGeometry.Boxes(piece))if(SingleBox(v,triangles,box))return true;return false;}
  static bool SingleBox(Float3[] v,int[] triangles,Panel box){var half=CandidateGeometry.HalfSize(box);var axes=new[]{new Float3(1,0,0),new Float3(0,1,0),new Float3(0,0,1)};foreach(var axis in axes)if(Separated(v,box.Center,half,axis))return false;for(int i=0;i<triangles.Length;i+=3){var a=v[triangles[i]];var b=v[triangles[i+1]];var c=v[triangles[i+2]];if(Separated(v,box.Center,half,Cross(Sub(b,a),Sub(c,a))))return false;foreach(var edge in new[]{Sub(b,a),Sub(c,b),Sub(a,c)})foreach(var axis in axes)if(Separated(v,box.Center,half,Cross(edge,axis)))return false;}return true;}
 }
}
